commands.command:
let MFAFails = SigninLogs | where ResultType != 0 | where AuthenticationRequirement == "multiFactorAuthentication" | project FailTime=TimeGenerated, UPN=UserPrincipalName, SrcIP=IPAddress;
let MFASuccess = SigninLogs | where ResultType == 0 | project SuccessTime=TimeGenerated, UPN=UserPrincipalName, SrcIP2=IPAddress;
MFAFails | join kind=inner MFASuccess on UPN | where SrcIP != SrcIP2 | where datetime_diff('minute', SuccessTime, FailTime) between (0 .. 5) | project UPN, FailTime, SrcIP, SuccessTime, SrcIP2
